create type public.user_role as enum ('admin','employee'); create type public.employee_status as enum ('active','inactive'); create type public.customer_status as enum ('unassigned','active','inactive'); create type public.conversation_status as enum ('open','closed'); create type public.message_direction as enum ('inbound','outbound'); create type public.message_sender_type as enum ('customer','employee','system'); create type public.message_type as enum ('text','image','video','audio','file','location','sticker','other'); create type public.message_delivery_status as enum ('received','pending','sent','failed');
create table public.employees(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,name text not null,email text not null,role public.user_role not null default 'employee',status public.employee_status not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.customers(id uuid primary key default gen_random_uuid(),name text not null,phone text,email text,status public.customer_status not null default 'unassigned',assigned_employee_id uuid references public.employees(id),note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint unassigned_has_no_owner check(status <> 'unassigned' or assigned_employee_id is null));
create table public.line_accounts(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,line_user_id text not null unique,display_name text,picture_url text,is_blocked boolean not null default false,last_message_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.students(id uuid primary key default gen_random_uuid(),name text not null,grade text,school text,status text not null default 'active',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.customer_students(customer_id uuid references public.customers(id) on delete cascade,student_id uuid references public.students(id) on delete cascade,relationship text,created_at timestamptz not null default now(),primary key(customer_id,student_id));
create table public.conversations(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,line_account_id uuid not null unique references public.line_accounts(id) on delete cascade,status public.conversation_status not null default 'open',last_message_at timestamptz,last_inbound_at timestamptz,last_outbound_at timestamptz,last_read_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,line_message_id text,webhook_event_id text unique,direction public.message_direction not null,sender_type public.message_sender_type not null,employee_id uuid references public.employees(id),message_type public.message_type not null default 'text',content_text text,payload_json jsonb,delivery_status public.message_delivery_status not null default 'received',error_code text,error_message text,sent_at timestamptz,created_at timestamptz not null default now());
create table public.webhook_events(id uuid primary key default gen_random_uuid(),webhook_event_id text not null unique,event_type text not null,is_redelivery boolean not null default false,source_user_id text,payload_json jsonb not null,processed_at timestamptz,processing_status text not null,error_message text,created_at timestamptz not null default now());
create table public.customer_notes(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,employee_id uuid not null references public.employees(id),content text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),actor_user_id uuid not null,action text not null,entity_type text not null,entity_id uuid,metadata jsonb,created_at timestamptz not null default now());
create index customers_assigned_idx on public.customers(assigned_employee_id); create index customers_search_idx on public.customers(name,phone,updated_at); create index messages_conversation_idx on public.messages(conversation_id,created_at); create index webhook_events_status_idx on public.webhook_events(processing_status);
create or replace function public.is_admin() returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from public.employees where user_id=auth.uid() and role='admin' and status='active'); $$;
create or replace function public.current_employee_id() returns uuid language sql security definer stable set search_path=public as $$ select id from public.employees where user_id=auth.uid() and status='active' limit 1; $$;
alter table public.employees enable row level security; alter table public.customers enable row level security; alter table public.line_accounts enable row level security; alter table public.students enable row level security; alter table public.customer_students enable row level security; alter table public.conversations enable row level security; alter table public.messages enable row level security; alter table public.customer_notes enable row level security; alter table public.audit_logs enable row level security; alter table public.webhook_events enable row level security;
create policy employees_read on public.employees for select using (user_id=auth.uid() or public.is_admin()); create policy customers_read on public.customers for select using(public.is_admin() or assigned_employee_id=public.current_employee_id()); create policy customers_update on public.customers for update using(public.is_admin() or assigned_employee_id=public.current_employee_id()) with check(public.is_admin() or assigned_employee_id=public.current_employee_id()); create policy customers_insert_admin on public.customers for insert with check(public.is_admin()); create policy line_accounts_read on public.line_accounts for select using(public.is_admin() or customer_id in(select id from public.customers where assigned_employee_id=public.current_employee_id())); create policy conversations_read on public.conversations for select using(public.is_admin() or customer_id in(select id from public.customers where assigned_employee_id=public.current_employee_id())); create policy messages_read on public.messages for select using(public.is_admin() or conversation_id in(select id from public.conversations where customer_id in(select id from public.customers where assigned_employee_id=public.current_employee_id()))); create policy messages_insert_employee on public.messages for insert with check(public.is_admin() or(employee_id=public.current_employee_id() and conversation_id in(select id from public.conversations where customer_id in(select id from public.customers where assigned_employee_id=public.current_employee_id())))); create policy notes_read on public.customer_notes for select using(public.is_admin() or customer_id in(select id from public.customers where assigned_employee_id=public.current_employee_id()));
